test('reduce', async () => {
  const h = await createHost();
  assert.equal((await h.reduce('a')).ok, false);
  await h.restock();
  await h.place('a', 2);
  assert.equal((await h.reduce('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 2 });
  assert.deepEqual(await h.reduce('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  assert.equal((await h.reduce('a')).ok, false);
  assert.deepEqual((await h.inFlight()).map((m) => [m.from, m.to, m.action, m.data]), [['a', 'inventory', 'Release', { qty: 1 }]]);
  // cancel before the reduction's Release arrives; deliver the cancel's Release first
  assert.deepEqual(await h.cancel('a'), { ok: true });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  await h.deliver(msgs[1].id);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0, open: true });
  // a 1-unit order cannot be reduced
  await h.place('b', 1);
  await h.deliverAll();
  assert.equal((await h.reduce('b')).ok, false);
  // reduce then expire
  await h.place('c', 1);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2, open: true });
  await h.expire('b');
  await h.cancel('c');
  await h.deliverAll();
  await h.place('d', 2);
