import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('place, confirm, stock', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
  await h.deliver(msgs[0].id);
  const m2 = await h.inFlight();
  assert.deepEqual({ from: m2[0].from, to: m2[0].to, action: m2[0].action, data: m2[0].data }, { from: 'inventory', to: 'a', action: 'Reserved', data: {} });
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  assert.deepEqual(await h.cancel('a'), { ok: true });
  const m3 = await h.inFlight();
  assert.deepEqual(m3.map((m) => [m.action, m.data]), [['Release', { qty: 1 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.cancel('a')).ok, false);
});

test('refusals', async () => {
  const h = await createHost();
  assert.equal((await h.place('a', 3)).ok, false);
  assert.equal((await h.place('a', 0)).ok, false);
  assert.equal(await h.order('a'), null);
  assert.equal((await h.cancel('zz')).ok, false);
  assert.equal(await h.order('zz'), null);
  assert.deepEqual(await h.place('a', 2), { ok: true });
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 2 });
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'rejected', qty: 2 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.restock(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0, open: true });
});

test('expire', async () => {
  const h = await createHost();
  assert.equal((await h.expire('a')).ok, false);
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), { ok: true });
  assert.deepEqual((await h.inFlight()).map((m) => [m.from, m.to, m.action, m.data]), [['a', 'inventory', 'Release', { qty: 1 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a', 1)).ok, false);
});

test('stocktake', async () => {
  const h = await createHost();
  assert.equal((await h.open()).ok, false);
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.close(), { ok: true });
  assert.equal((await h.close()).ok, false);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: false });
  assert.equal((await h.restock()).ok, false);
  // a Release is still taken while closed
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  // a Reserve is answered OutOfStock while closed
  await h.place('b', 1);
  await h.deliverAll();
  assert.deepEqual(await h.order('b'), { status: 'rejected', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.deepEqual(await h.open(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  await h.place('c', 2);
  await h.deliverAll();
  assert.deepEqual(await h.order('c'), { status: 'confirmed', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2, open: true });
});

test('cancel while pending', async () => {
  const h = await createHost();
  await h.place('a', 1);
  await h.place('b', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'cancelling', qty: 1 });
  assert.equal((await h.cancel('a')).ok, false);
  // deliver a's Reserve first
  const ra = (await h.inFlight()).find((m) => m.from === 'a')!;
  await h.deliver(ra.id);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.order('b'), { status: 'rejected', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});
